package com.wipro.spring; public class Student { private String studentId,studentName; private Test studentTest; public String getStudentId(){return studentId;} public void setStudentId(String v){studentId=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public Test getStudentTest(){return studentTest;} public void setStudentTest(Test v){studentTest=v;} public void print(){System.out.println(studentId+" | "+studentName+" | "+studentTest.getTestTitle()+" | "+studentTest.getTestMarks());} }